<style>
.cv-admin{--cv-bg:#101629;--cv-card:#151d33;--cv-card-2:#11192e;--cv-line:rgba(157,174,220,.16);--cv-muted:#8f9bbc;--cv-text:#f4f6ff;--cv-green:#00d987;color:var(--cv-text)}
.cv-admin *{box-sizing:border-box}.cv-admin .cv-hero{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:20px;padding:24px 26px;border:1px solid rgba(0,217,135,.2);border-radius:20px;background:radial-gradient(ellipse at 92% 0,rgba(0,217,135,.13),transparent 36%),linear-gradient(135deg,#18213a,#12192d);box-shadow:0 16px 40px rgba(0,0,0,.14)}
.cv-admin .cv-kicker{display:block;margin-bottom:7px;color:var(--cv-green);font-size:10px;font-weight:850;letter-spacing:.14em;text-transform:uppercase}.cv-admin h1.cv-title{margin:0;color:var(--cv-text);font-size:clamp(22px,2.6vw,30px);font-weight:850;letter-spacing:-.035em;line-height:1.2}.cv-admin .cv-intro{max-width:720px;margin:8px 0 0;color:var(--cv-muted);font-size:13px;line-height:1.55}.cv-admin .cv-hero-actions{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end}
.cv-admin .cv-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:18px}.cv-admin .cv-stat,.cv-admin .cv-panel{min-width:0;border:1px solid var(--cv-line);border-radius:16px;background:linear-gradient(145deg,var(--cv-card),var(--cv-card-2));box-shadow:0 10px 28px rgba(0,0,0,.1)}.cv-admin .cv-stat{padding:16px}.cv-admin .cv-stat span{display:block;color:var(--cv-muted);font-size:11px;font-weight:700}.cv-admin .cv-stat strong{display:block;margin-top:5px;color:var(--cv-text);font-size:24px;font-weight:850;line-height:1.1}.cv-admin .cv-stat small{color:var(--cv-muted);font-size:10px}
.cv-admin .cv-panel{padding:18px;margin-bottom:16px}.cv-admin .cv-panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:15px}.cv-admin .cv-panel-title{margin:0;color:var(--cv-text);font-size:17px;font-weight:800;letter-spacing:-.02em}.cv-admin .cv-panel-copy{margin:5px 0 0;color:var(--cv-muted);font-size:12px;line-height:1.5}
.cv-admin .cv-toolbar{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-bottom:14px}.cv-admin .cv-toolbar .form-control,.cv-admin .cv-toolbar .form-select{min-height:42px;border:1px solid var(--cv-line);border-radius:10px;background:#0e1528;color:var(--cv-text)}.cv-admin .cv-toolbar input{flex:1 1 240px}.cv-admin .cv-filters{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 14px}.cv-admin .cv-filter{display:inline-flex;align-items:center;gap:7px;padding:7px 10px;border:1px solid var(--cv-line);border-radius:999px;background:rgba(255,255,255,.025);color:#b8c2df;font-size:11px;font-weight:750;text-decoration:none}.cv-admin .cv-filter.is-active{border-color:rgba(0,217,135,.5);background:rgba(0,217,135,.09);color:var(--cv-green)}.cv-admin .cv-filter b{display:grid;min-width:18px;height:18px;place-items:center;padding:0 5px;border-radius:999px;background:rgba(255,255,255,.08);font-size:10px}
.cv-admin .cv-table-wrap{overflow:auto;border:1px solid var(--cv-line);border-radius:13px}.cv-admin .cv-table{width:100%;margin:0;border-collapse:separate;border-spacing:0;color:var(--cv-text)}.cv-admin .cv-table th{padding:11px 13px;border-bottom:1px solid var(--cv-line);background:#11182b;color:#8f9bbc;font-size:10px;font-weight:850;letter-spacing:.08em;text-align:left;text-transform:uppercase;white-space:nowrap}.cv-admin .cv-table td{padding:13px;border-bottom:1px solid rgba(157,174,220,.09);vertical-align:middle;font-size:12px}.cv-admin .cv-table tr:last-child td{border-bottom:0}.cv-admin .cv-table tbody tr:hover{background:rgba(255,255,255,.018)}.cv-admin .cv-primary{display:block;color:var(--cv-text);font-weight:800}.cv-admin .cv-secondary{display:block;margin-top:4px;color:var(--cv-muted);font-size:10px;line-height:1.4}.cv-admin .cv-status{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border:1px solid var(--cv-line);border-radius:999px;background:rgba(255,255,255,.035);color:#c0c9e2;font-size:10px;font-weight:800;white-space:nowrap}.cv-admin .cv-status:before{width:6px;height:6px;border-radius:50%;background:#8994b1;content:''}.cv-admin .cv-status--active,.cv-admin .cv-status--approved{border-color:rgba(0,217,135,.28);color:#43e5a7}.cv-admin .cv-status--active:before,.cv-admin .cv-status--approved:before{background:var(--cv-green)}.cv-admin .cv-status--rejected,.cv-admin .cv-status--revoked{border-color:rgba(255,111,139,.25);color:#ff93a8}.cv-admin .cv-status--rejected:before,.cv-admin .cv-status--revoked:before{background:#ff718c}.cv-admin .cv-status--suspended,.cv-admin .cv-status--more_information{border-color:rgba(255,190,82,.25);color:#ffd17d}.cv-admin .cv-status--suspended:before,.cv-admin .cv-status--more_information:before{background:#ffc454}
.cv-admin .cv-toolbar .btn,.cv-admin .btn{border-radius:9px;font-size:11px;font-weight:800}.cv-admin .cv-pagination{padding-top:14px}.cv-admin .cv-empty{padding:32px 16px;color:var(--cv-muted);text-align:center}
.cv-admin .cv-review-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(300px,.9fr);gap:16px;align-items:start}.cv-admin .cv-data-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.cv-admin .cv-data-item{min-width:0;padding:12px;border:1px solid var(--cv-line);border-radius:12px;background:rgba(5,10,22,.2)}.cv-admin .cv-data-item span{display:block;margin-bottom:5px;color:var(--cv-muted);font-size:10px;font-weight:750;text-transform:uppercase;letter-spacing:.06em}.cv-admin .cv-data-item strong{display:block;overflow-wrap:anywhere;color:var(--cv-text);font-size:12px;font-weight:700;line-height:1.5}.cv-admin .cv-form-section{padding-top:14px;margin-top:14px;border-top:1px solid var(--cv-line)}.cv-admin .cv-form-section:first-of-type{padding-top:0;margin-top:0;border-top:0}.cv-admin .cv-form-title{margin:0 0 10px;color:var(--cv-text);font-size:13px;font-weight:800}.cv-admin .cv-form-section .form-control{border:1px solid var(--cv-line);border-radius:10px;background:#0e1528;color:var(--cv-text);font-size:12px}.cv-admin .cv-form-section label{color:#c6cde3;font-size:11px;font-weight:700}.cv-admin .cv-check{display:flex;align-items:flex-start;gap:8px;margin-bottom:9px;color:#c7cfe3;font-size:11px;line-height:1.4}.cv-admin .cv-check input{flex:0 0 auto;margin-top:2px;accent-color:var(--cv-green)}
.cv-admin .cv-settings-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.cv-admin .cv-setting{min-width:0}.cv-admin .cv-setting label{display:block;margin-bottom:5px;color:#c6cde3;font-size:11px;font-weight:750}.cv-admin .cv-setting .form-control{min-height:40px;border:1px solid var(--cv-line);border-radius:9px;background:#0e1528;color:var(--cv-text);font-size:12px}.cv-admin .cv-note{padding:12px 14px;border:1px solid rgba(0,217,135,.18);border-radius:11px;background:rgba(0,217,135,.05);color:#aebada;font-size:11px;line-height:1.5}
@media(max-width:900px){.cv-admin .cv-review-grid{grid-template-columns:1fr}.cv-admin .cv-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.cv-admin .cv-hero{align-items:flex-start;flex-direction:column;padding:18px}.cv-admin .cv-hero-actions{justify-content:flex-start}.cv-admin .cv-stats{gap:8px}.cv-admin .cv-stat{padding:12px}.cv-admin .cv-stat strong{font-size:20px}.cv-admin .cv-panel{padding:13px}.cv-admin .cv-settings-grid,.cv-admin .cv-data-grid{grid-template-columns:1fr}.cv-admin .cv-toolbar>*{width:100%}.cv-admin .cv-filters{overflow:auto;flex-wrap:nowrap;padding-bottom:4px}.cv-admin .cv-filter{flex:0 0 auto}}
</style>
